import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.B3OtXxrP.js";const l="/blank/dev/screenshots/table-insert.gif",n="/blank/dev/screenshots/table-header.gif",d="/blank/dev/screenshots/table-cells.gif",k=JSON.parse('{"title":"Tables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tables.md","filePath":"guide/tables.md"}'),i={name:"guide/tables.md"};function r(c,e,h,p,b,u){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h1><p>Tables in Blank work like the rest of your writing: you type, press <code>Tab</code> to go to the next cell, and the table grows as you need it. The columns stay put while you type, and nothing is ever lost by a key pressed at the wrong time. Your tables are saved as plain markdown tables that GitHub, Obsidian, Typora and pandoc show as tables too.</p><img class="shot" src="'+l+'" alt="Mod T opens a grid, the arrow keys make it four columns wide, Enter inserts the table, Tab fills it cell by cell and the arrow key leads out of it"><h2 id="make" tabindex="-1">Make a table <a class="header-anchor" href="#make" aria-label="Permalink to &quot;Make a table {#make}&quot;">​</a></h2><p>There are two ways:</p><ul><li><p><strong><code>Mod</code> <code>T</code></strong> shows a small grid under the cursor. Pick the size with the arrow keys and press Enter, or point at the size and click. Want the usual? <code>Mod</code> <code>T</code> then Enter gives you three columns with a header row and two rows.</p></li><li><p><strong>Type the header.</strong> On an empty line, type the column titles between pipes and press Enter:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Name | Qty | Price |</span></span></code></pre></div><p>The line becomes a table with that header and an empty row, and the cursor waits in the first cell. Changed your mind? <code>Mod</code> <code>Z</code> gives you back the line as you typed it.</p><img class="shot" src="'+n+'" alt="Typing | Name | Role | and Enter turns the line into a table, which Tab then fills"></li></ul><p>The first row is the header. It&#39;s bold and tinted, and screen readers announce it with every cell.</p><h2 id="move" tabindex="-1">Move around <a class="header-anchor" href="#move" aria-label="Permalink to &quot;Move around {#move}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>Next cell, with its text selected so you can type over it</td></tr><tr><td><code>Shift</code> <code>Tab</code></td><td>Previous cell</td></tr><tr><td><code>Tab</code> in the last cell</td><td>Adds a row and moves into it</td></tr><tr><td>Arrow keys</td><td>Move through the text and from cell to cell</td></tr></tbody></table><p><strong>You can&#39;t get stuck in a table.</strong> The arrow keys leave it at every edge: down from the last row, up from the first, right from the end of the last cell and left from the start of the first. Blank always keeps an empty line before a table at the start of the document, after one at the end and between two tables, so there&#39;s always a place to click and write.</p><h2 id="cells" tabindex="-1">Write in a cell <a class="header-anchor" href="#cells" aria-label="Permalink to &quot;Write in a cell {#cells}&quot;">​</a></h2><p>A cell is a small page of its own. Bold, italic, code, links and images all work in it.</p><img class="shot" src="'+d+`" alt="Enter starts a second line in a cell; Shift and the left arrow select two cells, which Backspace clears"><ul><li><strong>Enter</strong> starts a new line in the cell.</li><li><strong>Enter on an empty line</strong> turns it into a new paragraph.</li><li><strong>Lists and quotes</strong>: <code>Mod</code> <code>8</code> starts a bullet list in the cell, <code>Mod</code> <code>9</code> a numbered one and <code>Mod</code> <code>G</code> a quote. Inside them, Enter continues the list as usual.</li></ul><p>Typing <code>1. </code>, <code>- </code> or <code>&gt; </code> at the start of a cell keeps the text as you typed it, since cells often hold values like <em>1. place</em> rather than lists. For the same reason, Blank doesn&#39;t capitalize the first word of a cell, so <code>kg</code>, <code>n/a</code> or <code>yes</code> stay as they are.</p><h2 id="select" tabindex="-1">Select and delete <a class="header-anchor" href="#select" aria-label="Permalink to &quot;Select and delete {#select}&quot;">​</a></h2><p><code>Shift</code> + arrow keys selects whole cells as soon as the selection crosses a cell border. The selected cells are tinted.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Backspace</code> or <code>Delete</code></td><td>Clears the selected cells, rows and columns stay</td></tr><tr><td><code>Mod</code> <code>A</code></td><td>Selects the cell, then the whole table, then everything</td></tr><tr><td><code>Backspace</code> on the whole table</td><td>Deletes the table</td></tr></tbody></table><p>To delete a table, press <code>Mod</code> <code>A</code> twice in it and then <code>Backspace</code>. Or press <code>Backspace</code> at the start of the line after the table: the first press selects the table, the second deletes it. A table you just made and haven&#39;t written in yet goes away with <code>Backspace</code> in its first cell. <code>Mod</code> <code>Z</code> brings anything back.</p><h2 id="saving" tabindex="-1">How tables are saved <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;How tables are saved {#saving}&quot;">​</a></h2><p>A table is saved as a markdown table, with the columns lined up so the file reads well in any text editor:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Name   | Qty | Price |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| ------ | --: | ----: |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Apples |   3 |  1.20 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Pears  |  12 |  0.80 |</span></span></code></pre></div><p>Line breaks in a cell are saved as <code>&lt;br&gt;</code>, and the colons in the second line keep the alignment of each column.</p><p>A markdown table holds one line of text per cell. When a table needs more, like a list or several paragraphs in a cell, Blank saves that one table as an HTML table in the same markdown file. GitHub, Obsidian, Typora and pandoc show it as a table as well. Once the table fits a markdown table again, Blank saves it as one.</p><p>Blank opens both kinds, so you can also open markdown files with tables written in other editors.</p><h2 id="export" tabindex="-1">PDF and Word <a class="header-anchor" href="#export" aria-label="Permalink to &quot;PDF and Word {#export}&quot;">​</a></h2><p>Tables go into your <a href="./files">PDF and Word documents</a> the way you see them in Blank: the tinted header, the lines between the rows and columns, the alignment of each column, merged cells, lists in cells and the caption above the table. Columns get their width from their content, like in the editor.</p><ul><li>A table longer than a page repeats its header row at the top of every page.</li><li>Rows stay whole instead of breaking across two pages, unless a row is too tall for one.</li><li>A caption never ends a page on its own: it moves to the next page with its table.</li></ul><p>In Word, tables are real Word tables and the caption uses Word&#39;s caption style, so the document stays easy to edit. When you <a href="./files#open-word-documents">open a Word document</a>, its tables come along with their merged cells, header rows and captions.</p>`,29)])])}const g=t(i,[["render",r]]);export{k as __pageData,g as default};
